import 'server-only';
import { z } from 'zod';

const Weather = z.object({ tempC: z.number(), summary: z.string() });

export async function getWeather(city: string) {
  const res = await fetch(`https://api.weather.example/v1?city=${encodeURIComponent(city)}`, {
    headers: { Authorization: `Bearer ${process.env.WEATHER_API_KEY}` },
    next: { revalidate: 600 },          // reuse for 10 minutes
    signal: AbortSignal.timeout(5000),  // fail fast
  });
  if (!res.ok) throw new Error(`Weather API failed: ${res.status}`);
  return Weather.parse(await res.json());
}

